import requests
import os
import json
import time
import base64
from urllib.parse import urlparse

# Redefining the function in the current context
HEADERS = {
    'accept': 'text/json',
    'Content-Type': 'application/json'
}


def _make_json_safe(value):
    """Convert a value into a JSON-serializable structure."""
    return json.loads(json.dumps(value, default=str, ensure_ascii=False))


def task_func(url, directory, metadata):
    if not isinstance(url, str) or not url.strip():
        raise TypeError("url is invalid")

    clean_url = url.strip()
    parsed = urlparse(clean_url)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise TypeError("url is invalid")

    try:
        directory_path = os.fspath(directory)
    except TypeError:
        raise FileNotFoundError("directory does not exist")

    if not os.path.isdir(directory_path):
        raise FileNotFoundError("directory does not exist")

    status_codes = []
    safe_metadata = _make_json_safe(metadata)

    for filename in sorted(os.listdir(directory_path)):
        file_path = os.path.join(directory_path, filename)
        if not os.path.isfile(file_path):
            continue

        try:
            with open(file_path, "rb") as file_obj:
                file_bytes = file_obj.read()

            payload = {
                "filename": filename,
                "file_content": base64.b64encode(file_bytes).decode("ascii"),
                "metadata": safe_metadata,
            }

            response = requests.post(clean_url, headers=HEADERS, json=payload)
            status_codes.append(response.status_code)
        finally:
            time.sleep(1)

    return status_codes
